/** 任意控件 id → 百科条目（DK5、SK3 这类归到整组的条目上）。 */
export function controlInfo(id) {
  if (!id) return null;
  if (/^DK\d+$/.test(id)) {
    const n = Number(id.slice(2));
    return { ...CONTROLS.DRUMKEYS, en: `Drum key ${n}`, zh: `第 ${n} 步${n % 4 === 1 ? `（第 ${(n + 3) / 4} 拍的正拍）` : ''}` };
  }
  if (/^SK\d$/.test(id)) {
    const n = Number(id.slice(2));
    return { ...CONTROLS.SYNTHKEYS, en: `Synth key ${n}`, zh: `音阶的第 ${n} 个音` };
  }
  return CONTROLS[id] || null;
}

